import { CommonModule } from '@angular/common';
import { Component, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import {
  IonButton,
  IonButtons,
  IonCol,
  IonContent,
  IonGrid,
  IonHeader,
  IonIcon,
  IonMenuToggle,
  IonRow,
  IonTitle,
  IonToolbar,
  Platform,
} from '@ionic/angular/standalone';
import {
  CdkVirtualScrollViewport,
  ScrollingModule,
} from '@angular/cdk/scrolling';
import { addIcons } from 'ionicons';
import { searchOutline } from 'ionicons/icons';
import { firstValueFrom, map, Subject, switchMap } from 'rxjs';
import { ImageTheme, ImageThemeType } from 'supabase/functions/images/themes';
import { getRoutePath, searchRoutePath } from '../app.routes';
import { AlertService } from '../common/alert/alert.service';
import { LoadingService } from '../common/loading/loading.service';
import { MenuToggleComponent } from '../common/menu/menu-toggle.component';
import { TimerService } from '../common/timer/timer.service';
import { SkeletonCardComponent } from '../common/verse/skeleton-card/skeleton-card.component';
import { EmptyComponent } from '../favorites/empty/empty.component';
import { Verse } from '../common/verse/verse';
import { ImageAttachment } from '../verse/attachment';
import { ImageAttachmentCardComponent } from '../verse/image-attachment-card/image-attachment-card.component';
import { VerseQuoteFactory } from '../verse/verse-quote-factory/verse-quote-factory.service';
import {
  ImagesService,
  ImageWithVerse,
  VeniceImageModel,
  DEFAULT_VENICE_MODEL,
} from './images.service';

@Component({
  selector: 'app-images',
  templateUrl: './images.page.html',
  styleUrls: ['./images.page.scss'],
  imports: [
    IonButton,
    IonButtons,
    IonCol,
    IonContent,
    IonGrid,
    IonHeader,
    IonIcon,
    IonRow,
    IonTitle,
    IonToolbar,
    CommonModule,
    FormsModule,
    EmptyComponent,
    SkeletonCardComponent,
    IonMenuToggle,
    MenuToggleComponent,
    ImageAttachmentCardComponent,
    ScrollingModule,
    RouterModule,
  ],
})
export class ImagesPage {
  readonly viewport = viewChild.required(CdkVirtualScrollViewport);

  private readonly alertService = inject(AlertService);
  private readonly loadingService = inject(LoadingService);
  private readonly verseQuoteFactory = inject(VerseQuoteFactory);
  private readonly platform = inject(Platform);
  private refresh$ = new Subject<void>();
  private readonly imagesService = inject(ImagesService);
  private readonly timerService = inject(TimerService);

  readonly searchRouterLink = [getRoutePath(searchRoutePath)];

  private allImages = signal<ImageAttachmentCard[]>([]);

  // Group images into rows based on screen size
  readonly imageRows = computed(() => {
    const images = this.allImages();
    const columnsPerRow = this.getColumnsPerRow();
    const rows: ImageAttachmentCard[][] = [];
    
    for (let i = 0; i < images.length; i += columnsPerRow) {
      rows.push(images.slice(i, i + columnsPerRow));
    }
    
    return rows;
  });

  images$ = this.refresh$.pipe(
    switchMap(() => this.imagesService.getImagesWithVerse()),
    map((images) => {
      const attachments = images.map((image) => this.createAttachment(image));
      this.allImages.set(attachments);
      return attachments;
    })
  );

  // Dynamic item size based on screen width
  get itemSize(): number {
    // iPad and larger: 750px card height + 16px gap
    // Mobile: 600px card height + 16px gap
    return this.platform.width() >= 768 ? 766 : 616;
  }

  constructor() {
    addIcons({ searchOutline });
  }

  private getColumnsPerRow(): number {
    // iPad and larger screens: 3 columns
    // Mobile: 1 column
    return this.platform.width() >= 768 ? 3 : 1;
  }

  ionViewWillEnter(): void {
    this.refresh$.next();
  }

  async regenerateImage(image: ImageAttachmentCard) {
    if (!image.prompt) {
      await this.alertService.createNotice({
        message: 'Cannot regenerate this image as it has no prompt stored',
        duration: 5000,
        positionAnchor: 'footer',
      });
      return;
    }

    if (!image.verse?.content) {
      await this.alertService.createNotice({
        message: 'Cannot regenerate this image as verse content is missing',
        duration: 5000,
        positionAnchor: 'footer',
      });
      return;
    }

    this.loadingService.setLoading(true);

    try {
      // All images are now square
      const { quote, source } = this.verseQuoteFactory.create(image.verse, 'square');
      const theme: ImageTheme = {
        type: ImageThemeType.Custom,
        content: image.prompt,
      };

      // Extract Venice model from stored model string (format: 'venice:model-name')
      let veniceModel: VeniceImageModel = DEFAULT_VENICE_MODEL;
      if (image.model?.startsWith('venice:')) {
        veniceModel = image.model.replace('venice:', '') as VeniceImageModel;
      }

      await this.imagesService.generateImage(
        image.verse.id,
        quote,
        source,
        theme,
        veniceModel
      );

      this.refresh$.next();
      // Not sure why but this doesn't scroll if it's awaited
      firstValueFrom(this.timerService.timer(1000)).then(() => {
        this.viewport().scrollToOffset(0, 'smooth');
      });
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : 'An error occurred';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
      });
    } finally {
      this.loadingService.setLoading(false);
    }
  }

  async removeImage(image: ImageAttachmentCard) {
    await this.imagesService.deleteImage(image.id, image.storage_path);
    this.refresh$.next();
  }

  // Track by function for better performance
  trackByImageId(index: number, item: ImageAttachmentCard): string {
    return item.id.toString();
  }

  // Track by function for rows
  trackByRowIndex(index: number): number {
    return index;
  }

  private createAttachment(image: ImageWithVerse) {
    const book = image.verse.book;
    const chapter = image.verse.chapter;
    const startVerse = image.verse.start_verse;
    const endVerse = image.verse.end_verse;
    const title = `${book} ${chapter}:${startVerse}${
      endVerse !== startVerse ? `-${endVerse}` : ''
    }`;
    return {
      ...image,
      title,
      type: 'Image',
      routerLink: ['verse', `${image.verse.id}`],
    } as ImageAttachmentCard;
  }
}

type ImageAttachmentCard = ImageAttachment & {
  title: string;
  routerLink: string[];
  verse: Verse;
};
